result = GRAPH.CALCULATE(
    max_engineer_age=MAX(people.WHERE(job == 'engineer').age)
).people.WHERE(
    age > max_engineer_age
).CALCULATE(
    count_of_people_older_than_engineers=COUNT()
)

result = GRAPH.CALCULATE(
    global_avg_salary=ROUND(AVG(instructors.salary), 5) # Calculate global average and round for precision
).instructors.PARTITION(
    name="department_stats", by=dept_name
).CALCULATE(
    department_name_alias=_key, # Use _key to correctly reference the partition key (dept_name)
    avg_dept_salary=ROUND(AVG(instructors.salary), 5), # Calculate department average and round for precision
    min_dept_salary=MIN(instructors.salary)
).WHERE(
    avg_dept_salary > global_avg_salary # Compare the rounded averages
).CALCULATE(
    department_name=department_name_alias,
    minimum_salary_in_dept=min_dept_salary
)

# Filter countries where English is NOT spoken and sum their populations.
population_in_non_english_speaking_countries = world_1.countries.WHERE(
    ~HAS(countrylanguages.WHERE(language == 'English'))
).CALCULATE(
    total_population_non_english_speaking_countries=SUM(population)
)

# Step 1: Calculate the global average checking balance across all accounts.
# The balance field is a string as per the schema, so it must be converted to a float for the average calculation.
global_avg_balance_data = GRAPH.CALCULATE(
    avg_checking_balance=AVG(checkings.balance.TO_FLOAT())
)

# Step 2: Filter checkings accounts whose balance is below the calculated global average.
# Then, explicitly join with accounts and select the name of the associated account.
result = GRAPH.checkings.WHERE(
    checkings.balance.TO_FLOAT() < global_avg_balance_data.avg_checking_balance
).JOIN(
    GRAPH.account
).ON(
    checkings.custid == account.custid
).CALCULATE(
    account_name=account.name
)
